package com.project.web.controller.system;
import java.util.*;import javax.servlet.http.HttpSession;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.apache.shiro.authz.annotation.RequiresPermissions;import org.springframework.http.*;import com.project.common.utils.ShiroUtils;import com.project.system.service.FinanceService;
@Controller @RequestMapping("/campus/finance") public class FinanceController{
 @Autowired private FinanceService service;
 private void token(HttpSession s,String t){if(t==null||!t.equals(s.getAttribute("financeToken")))throw new IllegalArgumentException("页面已过期，请刷新");}
 @RequiresPermissions("campus:finance:view") @GetMapping public String page(Model m,HttpSession s){if(s.getAttribute("financeToken")==null)s.setAttribute("financeToken",UUID.randomUUID().toString());m.addAttribute("token",s.getAttribute("financeToken"));for(String key:Arrays.asList("run","import","handle","review","export"))m.addAttribute("can"+key,org.apache.shiro.SecurityUtils.getSubject().isPermitted("campus:finance:"+key));m.addAttribute("monthStart",java.time.LocalDate.now(java.time.ZoneId.of("Asia/Shanghai")).withDayOfMonth(1).toString());m.addAttribute("today",java.time.LocalDate.now(java.time.ZoneId.of("Asia/Shanghai")).toString());return "finance";}
 @RequiresPermissions("campus:finance:view") @GetMapping("/merchants") @ResponseBody public Object merchants(){return service.merchants();}
 @RequiresPermissions("campus:finance:view") @GetMapping("/overview") @ResponseBody public Object overview(String start,String end,Long merchant){return service.overview(start,end,merchant);}
 @RequiresPermissions("campus:finance:run") @PostMapping("/internal") @ResponseBody public Object internal(String start,String end,String token,HttpSession s){token(s,token);return Collections.singletonMap("batchId",service.internal(start,end,ShiroUtils.getUserId()));}
 @RequiresPermissions("campus:finance:import") @PostMapping("/import") @ResponseBody public Object importBill(long merchant,String start,String end,@RequestParam MultipartFile file,String token,HttpSession s){token(s,token);return Collections.singletonMap("batchId",service.importBill(merchant,start,end,file,ShiroUtils.getUserId()));}
 @RequiresPermissions("campus:finance:view") @GetMapping("/batches") @ResponseBody public Object batches(String kind,Long merchant,@RequestParam(defaultValue="1")int page){return service.batches(kind,merchant,page);}
 @RequiresPermissions("campus:finance:view") @GetMapping("/lines") @ResponseBody public Object lines(String batch,@RequestParam(defaultValue="false")boolean differences,String handling,@RequestParam(defaultValue="1")int page,String scope){return service.lines(batch,differences,handling,page,scope);}
 @RequiresPermissions("campus:finance:handle") @PostMapping("/handle") @ResponseBody public Object handle(long id,String note,String evidence,String token,HttpSession s){token(s,token);service.handle(id,note,evidence,ShiroUtils.getUserId());return Collections.singletonMap("ok",true);}
 @RequiresPermissions("campus:finance:review") @PostMapping("/review") @ResponseBody public Object review(long id,boolean accept,String note,String token,HttpSession s){token(s,token);service.review(id,accept,note,ShiroUtils.getUserId());return Collections.singletonMap("ok",true);}
 @RequiresPermissions("campus:finance:review") @PostMapping("/archive") @ResponseBody public Object archive(String batch,String token,HttpSession s){token(s,token);service.archive(batch,ShiroUtils.getUserId());return Collections.singletonMap("ok",true);}
 @RequiresPermissions("campus:finance:handle") @PostMapping("/evidence") @ResponseBody public Object evidence(@RequestParam MultipartFile file,String token,HttpSession s){token(s,token);return Collections.singletonMap("id",service.evidence(file,ShiroUtils.getUserId()));}
 @RequiresPermissions("campus:finance:view") @GetMapping("/file/{id}") public ResponseEntity<byte[]> file(@PathVariable String id){Map<String,Object>x=service.file(id);return ResponseEntity.ok().header("Cache-Control","private, no-store").header("X-Content-Type-Options","nosniff").contentType(MediaType.parseMediaType((String)x.get("mime"))).body((byte[])x.get("content"));}
 @RequiresPermissions("campus:finance:export") @GetMapping("/source") public ResponseEntity<byte[]> source(String batch){Map<String,Object>b=service.batch(batch);if(b.get("source_file_id")==null)throw new IllegalArgumentException("该批次没有导入账单");Map<String,Object>f=service.file((String)b.get("source_file_id"));String ext=String.valueOf(b.get("source_name")).toLowerCase(Locale.ROOT).endsWith(".xlsx")?"xlsx":"csv";return ResponseEntity.ok().header("Content-Disposition","attachment; filename=source-"+batch+"."+ext).header("Cache-Control","no-store").contentType(MediaType.APPLICATION_OCTET_STREAM).body((byte[])f.get("content"));}
 @RequiresPermissions("campus:finance:export") @GetMapping("/export") public ResponseEntity<byte[]> export(String batch){return ResponseEntity.ok().header("Content-Disposition","attachment; filename="+batch+".csv").header("Cache-Control","no-store").contentType(MediaType.parseMediaType("text/csv;charset=UTF-8")).body(service.export(batch,ShiroUtils.getUserId()));}
 @RequiresPermissions("campus:finance:view") @GetMapping("/template") public ResponseEntity<byte[]> template(){return ResponseEntity.ok().header("Content-Disposition","attachment; filename=merchant-bill-template.csv").contentType(MediaType.parseMediaType("text/csv;charset=UTF-8")).body(("\ufeff"+FinanceService.HEADER+"\r\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 @ExceptionHandler(IllegalArgumentException.class) @ResponseBody @ResponseStatus(HttpStatus.BAD_REQUEST) public Object error(IllegalArgumentException e){return Collections.singletonMap("error",e.getMessage());}
}
